def estandarizar_booleano(valor):
    if pd.isna(valor):
        return valor
    valor = str(valor).strip().lower()
    if valor in ['1', 'true', 'positivo', 'ingresado', 'si', 'sí']:
        return 1
    if valor in ['0', 'false', 'negativo', 'no', 'ambulatorio']:
